/bin/bash -lc "python -c 'import json,collections; rows=[json.loads(x) for x in open(\"pilot/peval/pairs.jsonl\")]; print(\"keys\",sorted(rows[0]));
for keys,name in [((\"instruction\",\"memory_text\"),\"exact_pair\"),((\"memory_text\",),\"memory\"),((\"instruction\",),\"instruction\")]:
 g=collections.defaultdict(list)
 for row in rows:g[tuple(row[k] for k in keys)].append(row)
 c=[v for v in g.values() if len({x[\"P\"] for x in v})>1]
 print(name,\"unique\",len(g),\"duplicate_groups\",sum(len(v)>1 for v in g.values()),\"P_conflict_groups\",len(c),\"rows_in_conflicts\",sum(map(len,c)))
 print([[ (x.get(\"cell\"),x.get(\"P\"),x.get(\"archetype\"),x.get(\"family_idx\"),x.get(\"target_sibling\"),x.get(\"memory_id\")) for x in v] for v in c[:3]])'
python -c 'import json,pprint; d=json.load(open(\"pilot/peval/P_EVAL_RESULTS.json\")); print(d.keys()); pprint.pp(d)'
python -c 'import json,pprint; pprint.pp(json.load(open(\"pilot/audit/results/equivalence.json\")))'
python -c 'import json,pprint; pprint.pp(json.load(open(\"pilot/peval/phi_d/out/frozen/summary_final.json\")))'"

